 SELECT ((((p_demo_read)) OR (NOT (((p_demo))) AND coalesce((((p_occasion_user.is_editor_order_view))),false)))),
   ((NOT ((p_demo)) AND coalesce(((p_occasion_user.is_editor_order)),false))),
   ((viewer) OR (editor)),((editor) OR (unit_editor)),
   p_occasion IS NOT NULL AND ((actor_present) AND coalesce((unit_editor),false)),
   ((p_demo_read) OR (editor) OR (manager) OR coalesce((p_unit_user.is_editor_view),false) OR (admin))
 INTO order_reader,order_writer,map_reader,form_author,layout_author,administration_navigation;
 RETURN jsonb_build_object(
    'ticket_layouts.read',layout_author,
    'ticket_layouts.write',layout_author,
    'orders.read',order_reader,
    'orders.write',order_writer,
    'occasions.delete',p_occasion IS NOT NULL AND unit_manager,
    'bank_accounts.unit.manage',unit_manager,
    'schedule.feedback.delete',admin,
    'navigation.email_history',admin,
    'orders.delete',p_occasion IS NOT NULL AND ((unit_manager) OR (unit_editor) OR (admin)),
    'occasions.create',((unit_manager) OR (unit_editor)),
    'occasions.write',p_occasion IS NOT NULL AND ((unit_editor) AND (unit_editor)),
    'users.write',p_occasion IS NOT NULL AND actor_present AND ((manager) OR (admin) OR (unit_editor)),
    'emails.custom.send',((editor) OR (order_writer)),
    'email_templates.occasion.read',((viewer) OR (order_reader)),
    'email_templates.occasion.write',((editor) OR (order_writer)),
    'email_templates.unit.read',((unit_manager) OR (unit_editor) OR coalesce((p_unit_user.is_editor_view),false)),
    'email_templates.unit.write',unit_editor,
    'media.occasion.write',((editor) OR (order_writer)),
    'media.unit.write',unit_editor,
    'unit.settings.write',unit_manager,
    'unit.legal_profile.write',unit_manager,
    'unit.administration.read',coalesce(p_unit_user.is_editor_view,false),
    'companions.assign',((actor_present) AND (editor)),
    'navigation.schedule_entry_check',(coalesce((p_occasion_user.is_approver),false)),
    'navigation.cleaning_crew',(coalesce((p_occasion_user.is_cleaning_crew),false)),
    'navigation.organization_settings',admin,
    'navigation.occasion_settings',unit_editor OR p_demo_read,
    'forms.create',p_occasion IS NOT NULL AND form_author,
    'forms.write',p_occasion IS NOT NULL AND NOT p_demo AND form_author,
    'forms.delete',p_occasion IS NOT NULL AND form_author,
    'forms.catalog.read',p_occasion IS NOT NULL AND ((viewer) OR (order_reader) OR (form_author)),
    'forms.copy.source',(coalesce((p_occasion_user.is_editor_view),false) OR coalesce((p_unit_user.is_editor_view),false)),
    'forms.copy.target',editor,
    'occasions.editor.read',p_occasion IS NOT NULL AND (coalesce((viewer),false) OR coalesce((manager),false) OR coalesce((admin),false)),
    'news.write',editor) || jsonb_build_object(
    'schedule.write',editor,
    'schedule.editor.read',viewer,
    'schedule.participants.read',((viewer) OR (editor) OR (admin)),
    'schedule.feedback.read',((viewer) OR (admin)),
    'speakers.write',editor,
    'speakers.editor.read',viewer,
    'services.write',manager,
    'participants.write',((manager) OR (admin)),
    'participants.contacts.read',((editor) OR (manager) OR (coalesce(p_occasion_user.is_approver,false))),
    'forms.sale_opening_subscribers.read',((editor) OR (manager) OR (coalesce(p_occasion_user.is_approver,false))),
    'groups.assignments.write',((editor) OR (((manager)) OR ((admin)) OR ((unit_editor)))),
    'blueprints.write',((editor) OR (manager)),
    'inventory.copy.target',((order_writer) OR (unit_manager)),
    'activities.write',editor,
    'activities.editor.read',map_reader,
    'information.write',editor,
    'unit_information.read',coalesce(p_unit_user.is_editor_view,false),
    'unit_information.write',unit_editor,
    'scanner.settings.write',((actor_present) AND ((editor) OR (order_writer))),
    'reception.use',((p_reception_enabled) AND (coalesce((p_occasion_user.is_receptionist),false) OR (manager) OR (admin))),
    'information.editor.read',viewer,
    'map.places.write',editor,
    'groups.editor.read',map_reader,
    'groups.create',editor,
    'map.editor.read',map_reader,
    'reception.participants.manage',((manager) OR (admin)),
    'unit_users.read',(coalesce((p_unit_user.is_manager),false) OR coalesce((p_unit_user.is_editor),false) OR coalesce((p_unit_user.is_editor_view),false)),
    'unit_users.write',unit_manager,
    'navigation.admin_app',administration_navigation,
    'navigation.admin_web',administration_navigation OR p_has_units,
    'navigation.administration',p_demo_read OR coalesce(p_unit_user.is_editor_view,false) OR viewer,
    'navigation.unit_workspace',(coalesce((p_current_unit_listed),false) OR coalesce((unit_editor),false) OR coalesce((unit_manager),false) OR coalesce((p_unit_user.is_editor_view),false)));
END;
$$;
